const listBankAccountsByNormalizedIdentifiers = `-- name: ListBankAccountsByNormalizedIdentifiers :many
SELECT id, realm_id, bank_name, account_number, rib, iban, ledger_account_code, currency, created_at, updated_at
FROM shadow_erp.bank_accounts
WHERE realm_id = $1
  AND (
      ($2::text <> '' AND regexp_replace(upper(account_number), '[^A-Z0-9]', '', 'g') = $2::text)
      OR ($3::text <> '' AND regexp_replace(upper(COALESCE(rib, '')), '[^A-Z0-9]', '', 'g') = $3::text)
      OR ($4::text <> '' AND regexp_replace(upper(COALESCE(iban, '')), '[^A-Z0-9]', '', 'g') = $4::text)
  )
ORDER BY id
`

type ListBankAccountsByNormalizedIdentifiersParams struct {
	RealmID                 string
	NormalizedAccountNumber string
	NormalizedRib           string
	NormalizedIban          string
}

// Values are normalized by the caller and compared without separators or case.
// The resolver must hold rather than select when this returns zero or multiple rows.
func (q *Queries) ListBankAccountsByNormalizedIdentifiers(ctx context.Context, arg ListBankAccountsByNormalizedIdentifiersParams) ([]ShadowErpBankAccount, error) {
	rows, err := q.db.Query(ctx, listBankAccountsByNormalizedIdentifiers,
		arg.RealmID,
		arg.NormalizedAccountNumber,
		arg.NormalizedRib,
		arg.NormalizedIban,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ShadowErpBankAccount
	for rows.Next() {
		var i ShadowErpBankAccount
		if err := rows.Scan(
			&i.ID,
			&i.RealmID,
			&i.BankName,
			&i.AccountNumber,
			&i.Rib,
			&i.Iban,
			&i.LedgerAccountCode,
			&i.Currency,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

